"s":0,"t":"lift","n":"Lower single-leg/power + upper pull","nt":"Prevention block after the lifts."},{"k":"k12","d":5,"s":0,"t":"peloton","n":"Peloton Zone 2","rk":"zone2","m1":45,"m2":60},{"k":"k12","d":6,"s":0,"t":"lift","n":"Full body","op":true,"nt":"Optional third lift."},{"k":"k12","d":6,"s":1,"t":"walk","n":"Ruck","m1":45,"m2":60,"st":"Ruck at Zone 2 heart rate.","op":true},{"k":"k12","d":6,"s":2,"t":"golf","n":"Golf: short game","st":"Putting and chipping, 1–2x a week. Log balls hit in the notes; check the knee next morning.","g":"golf_short","op":true},{"k":"k12","d":6,"s":3,"t":"golf","n":"Golf: full swing (staged)","st":"Half wedges → half irons → full irons → driver last. Each stage 2 weeks minimum with a normal next morning.","g":"golf_full","op":true}]$j$::jsonb)
  as v(k text, d smallint, s smallint, t text, n text, rk text, m1 smallint, m2 smallint,
       st text, g text, op boolean, nt text)
join v1_blocks vb on vb.k = v.k
join public.program_blocks b on b.program_id = p.id and b.name = vb.name
on conflict (block_id, day_of_week, sort_order) do update
  set session_type = excluded.session_type, name = excluded.name, ride_kind = excluded.ride_kind,
      minutes_min = excluded.minutes_min, minutes_max = excluded.minutes_max,
      structure = excluded.structure, gate_key = excluded.gate_key,
      is_optional = excluded.is_optional, notes = excluded.notes,
      upper_template_id = null, deleted_at = null;

-- 7. Exercises. Defaults when a key is missing: readiness any, measure reps,
-- bilateral, bodyweight, not a quad set. Cues come from the library below.
with o as (select user_id as uid from public.profiles order by created_at limit 1)
insert into public.program_exercises
  (user_id, program_session_id, exercise_order, exercise_name, block_part, category, primary_muscle,
   readiness_requirement, measure, side_mode, load_kind, sets_min, sets_max, reps_min, reps_max,
   rir_target, seconds_target, distance_meters_target, tempo, gate_key, extra_gate_key,
   substitute_name, substitute_load_kind, substitute_reps_min, substitute_reps_max,
   from_week, until_week, counts_as_quad_set, cue, notes)
select o.uid, s.id, v.o, v.n, v.pt, v.c, v.mu,
  coalesce(v.rd, 'any'), coalesce(v.ms, 'reps'), coalesce(v.sd, 'bilateral'), coalesce(v.l, 'bodyweight'),
  v.s1, v.s2, v.r1, v.r2, v.ir, v.sc, v.dm, v.tp, v.g, v.g2, v.sb, v.sl, v.sr1, v.sr2,
  v.fw, v.uw, coalesce(v.q, false), cues.c ->> v.n, v.nt
from o join public.training_programs p on p.user_id = o.uid and p.name = 'ACL return'
cross join (select $j${"45° Cut":"Plant the outside foot, hips low, knee over the toes.","Ankle Dorsiflexion Knee-to-Wall":"Heel down, drive the knee past the toes.","Band Anti-Rotation Press":"Stand or half-kneel on the right knee; don't let the band turn you.","Band Step-and-Rotate":"Step, then turn through the hips, not the knee.","Barbell Back Squat (to parallel)":"Brace, sit between the hips, drive up evenly.","Barbell Bench Press":"Feet flat; do not tuck the left foot under the bench.","Barbell Hip Thrust":"Ribs down, pause 1 s at the top.","Barbell Pin Squat (to 90°)":"Pins at 90°. Touch, don't bounce.","Bent-Knee Calf Raise":"Seated, DB on the knee, full range.","Box Jump (12\", step down)":"Land soft on the box; step down, never jump down.","Box Jump (18\", step down)":"Land soft on the box; step down, never jump down.","Broad Jump to Stick":"Two-foot jump, land quiet, hold 2 s.","Chin-Up":"Reach the bar from the bench; step down with the right leg. No jumping or dropping.","Close-Grip Bench Press":"Feet flat; elbows tucked.","Copenhagen Side Plank (long lever)":"Ankle on the bench, hips stacked, body straight.","Copenhagen Side Plank (short lever)":"Knee on the bench, hips stacked, body straight.","Cuff Knee Extension (90→0°)":"3 s down to full extension, no swing.","Cuff Knee Extension (90→45°)":"3 s down, stop at 45° until full-range gate.","Cutting (45°→90°)":"Hips low into the cut, knee over the toes.","DB Single-Leg RDL":"Hinge at the hip, hips square, soft knee.","DB Step-Up (12\")":"Push through the top foot only.","DB Step-Up (bench)":"Push through the top foot only.","Dead Bug":"Low back flat on the floor; exhale as you reach.","Deceleration Drill":"Accelerate 5 m, stop in two steps, hips low.","Depth Drop to Stick (12\")":"Step off, land quiet, stick 2 s.","Double-Leg Pogo":"Stiff ankles, quick contacts, quiet landings.","Double-Leg Pogo (low)":"Stiff ankles, small quiet bounces.","Drop-Squat Landing":"Drop fast to a quarter squat, land quiet, stick it.","Dumbbell Curl":"No swing, full range.","Dumbbell Row":"Bench-supported; pull to the hip.","Dumbbell Shoulder Press":"Ribs down, press straight up.","Eccentric Lateral Step-Down (6\")":"4 s down, tap the heel, knee over the second toe.","Face Pull":"Pull to the eyes, thumbs back.","Front Squat":"Elbows high, torso upright, knees forward.","Gait Drill":"Heel first, straighten the knee, even steps to the beat.","Hammer Curl":"Neutral grip, no swing.","Heel-Elevated Goblet Squat (to 90°)":"Heels up, torso tall, knees forward over the toes.","Incline Dumbbell Press":"Shoulder blades back; control the bottom.","Isometric Knee Extension (60°)":"5-s ramp, don't jerk; strap level and perpendicular to the shin.","Isometric Knee Extension (90°)":"5-s ramp, don't jerk; strap level and perpendicular to the shin.","Jump Squat":"Full reset each rep; land soft and stick.","Lateral Bound to Stick":"Stick the landing for 2 s before the next rep.","Lateral Raise":"Lead with the elbows; stop at shoulder height.","Lateral Shuffle / Reactive Drill":"Stay low, react, don't cross the feet.","Lead-Leg Posting Drill":"Step and post onto the left, hold 2 s, knee over the foot.","Nordic Curl (eccentric, band-assisted)":"Lower as slow as you can; catch with hands.","Perturbation Balance":"Soft knee, level hips; recover without hopping.","Perturbation Balance (cushion)":"Soft knee, level hips; recover without hopping.","Plank":"Squeeze the glutes, ribs down.","Pull-Up":"Reach the bar from the bench; step down with the right leg. No jumping or dropping.","Rear Delt Fly":"Chest on the incline bench; lead with the pinkies.","Rear-Foot-Elevated Split Squat (to 90°)":"Weight on the front leg; knee tracks over the toes.","Shuffle-to-Sprint (10 m)":"Two shuffles, then sprint 10 m.","Single-Leg Bound":"Bound onto the other leg; stick each landing.","Single-Leg Broad Jump to Stick":"Jump forward, land on the same leg, hold 2 s.","Single-Leg Calf Raise":"Full stretch off the plate, 1 s pause on top.","Single-Leg Forward Hops (x3)":"Three hops in a row; stick the last one.","Single-Leg Hop in Place":"Quiet landings, knee over the toes.","Single-Leg Landing to Stick":"Land on one leg, knee over the toes, hold 2 s.","Slider Hamstring Curl":"Hips up the whole set; slide out slowly.","Snap-Down to Stick":"Land quiet, knees over toes, hold 2 s.","Spanish Squat":"Band behind the knees, shins vertical, no deeper than 60°.","Split Squat (to 90°)":"Front knee to 90°, tracking over the toes.","Sprint Acceleration (10–20 m)":"Push the ground back; build to speed.","Squat to Calf Raise":"Smooth squat, drive up onto the toes.","Suitcase Carry":"Stand tall; don't lean toward the weight.","Tricep Extension":"Elbows in, full stretch.","Weighted Dead Bug":"Low back flat on the floor; exhale as you reach."}$j$::jsonb as c) as cues
